import React, { useMemo, useState } from "react"
import { cn } from "@heroui/react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { CourseQaComposer } from "@sb-components/starci/blocks/learn/CourseQaComposer/CourseQaComposer"
import { QaConversationHeader } from "@sb-components/starci/blocks/learn/QaConversationHeader/QaConversationHeader"
import { QaChatBubble } from "@sb-components/starci/blocks/learn/QaChatBubble/QaChatBubble"
import { QaReactionBar } from "@sb-components/starci/blocks/learn/QaReactionBar/QaReactionBar"
import { QaMessageBubble } from "@sb-components/starci/blocks/learn/QaMessageBubble/QaMessageBubble"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { FillAvailable } from "@sb-components/frames/FillAvailable/FillAvailable"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { ComponentTypeWithSkeleton , SkeletonProps } from "@sb-components/frames/_slot"

/**
 * BLOCK — `QaQuestionThread`: ONE course-Q&A conversation — a collapsed social
 * inbox row that presses open into the full conversation (header, question
 * bubble, every answer, a bottom composer). See the component file header for
 * the full contract, the local-state judgement call, and the assumed-contract
 * risk on the four sibling blocks that did not exist yet when this was written.
 */

/** Reaction kinds a message in this thread can carry (mirrors backend `ReactionType`). */
export type QaReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** Minimal identity carried by whoever wrote the question or an answer. */
export interface QaQuestionThreadAuthor {
    /** Stable id — drives "is this the viewer's own message" checks. */
    id: string
    /** Display name, already resolved by the caller (falls back to username upstream). */
    displayName: string
    /** Avatar image url. Omitted → `Avatar`'s own generated/initials fallback chain. */
    avatarUrl?: string
}

/** Where a question was asked — drives the scope chip's own wording (§14d.1). */
export type QaQuestionThreadScope =
    | { kind: "lesson", lessonTitle: string }
    | { kind: "general" }

/** One answer — or, once flattened, one reply-to-a-reply — in the conversation. */
export interface QaThreadAnswer {
    /** Stable id — the React key, and what accept/react actions target. */
    id: string
    /** Answer body, as authored markdown. */
    body: string
    /** Who wrote this answer. */
    author: QaQuestionThreadAuthor
    /** Already-formatted relative time, e.g. "2 hours ago" — no i18n layer at this tier. */
    createdTimeAgo: string
    /** `true` → this is the asker's chosen answer; only ever true on a DIRECT (top-level) answer. */
    isAcceptedAnswer?: boolean
    /** Total reactions on this answer. */
    reactionCount: number
    /** The viewer's own reaction on this answer, or null. */
    myReaction: QaReactionType | null
    /** Already-loaded flattened replies to THIS answer — rendered as sibling bubbles, not indented. */
    replies?: ReadonlyArray<QaThreadAnswer>
}

/** The question this whole thread is about. */
export interface QaQuestionThreadQuestion {
    /** Question primary id. */
    id: string
    /** Who asked it. */
    author: QaQuestionThreadAuthor
    /** Already-formatted relative time, e.g. "2 hours ago". */
    createdTimeAgo: string
    /** `true` → a pin glyph rides beside the asker's name (founder moderation). */
    isPinned?: boolean
    /** `true` → the asker is the founder (drives the founder-author badge). */
    isFounderAuthor?: boolean
    /** Question body, as authored markdown. */
    body: string
    /** Which lesson (or "course-wide") this question belongs to. */
    scope: QaQuestionThreadScope
    /** Total answers (top-level + replies) — the SSOT count, independent of how many `answers` are loaded below. */
    replyCount: number
    /** `true` → at least one answer came from the course founder. */
    answeredByFounder?: boolean
    /** Total reactions on the question itself (the question is a comment too). */
    reactionCount: number
    /** The viewer's own reaction on the question, or null. */
    myReaction: QaReactionType | null
    /** Already-loaded top-level answers — this design-system block does no fetching (§13). */
    answers: ReadonlyArray<QaThreadAnswer>
}

/** The signed-in viewer's identity — pass-through shape, matches `src`'s real `QuestionRow` contract 1:1. */
export interface QaQuestionThreadViewer {
    username: string
    avatar?: string
}

/** Props for {@link QaQuestionThread}. */
export interface QaQuestionThreadProps {
    /** The question to render. */
    question: QaQuestionThreadQuestion
    /** Current viewer id — drives own-bubble alignment + accept-answer eligibility; null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the bottom composer's avatar; null when signed out. */
    currentUser: QaQuestionThreadViewer | null
    /** Called after a new answer is posted — bumps the parent roll-up's aggregates. */
    onAnswered?: () => void
    /**
     * `true` → the collapsed row draws its own shimmer mirror and stops accepting
     * presses (there is no real conversation to open yet). See the file header
     * for why this never reaches `SurfaceCard.Pressable`'s own generic flag.
     */
    isSkeleton?: boolean
}

/** The block's own scope → label vocabulary (§14d.1) — never handed in pre-formatted. */
const scopeLabel = (scope: QaQuestionThreadScope): string =>
    scope.kind === "lesson" ? `Lesson: ${scope.lessonTitle}` : "General"

/** The block's own status → label vocabulary (§14d.1). */
const statusLabel = (replyCount: number, answeredByFounder?: boolean): string => {
    if (replyCount <= 0) {
        return "Unanswered"
    }
    return answeredByFounder ? "Instructor answered" : "Answered"
}

/** Options controlling which chips {@link buildQuestionChips} builds. */
interface QaQuestionChipsOptions {
    /** `true` → both chips draw their shimmer mirror. */
    isSkeleton: boolean
    /**
     * `true` → a third, quiet reply-count fact rides beside the two chips. The
     * collapsed row needs it (no `QaConversationHeader` around to say it
     * elsewhere); the expanded question bubble does not, since the header above
     * it already carries the same count.
     */
    includeReplyCount: boolean
}

/**
 * The scope + status chip pair shared by the collapsed row and the expanded
 * question bubble — built ONCE so the two never drift on wording.
 */
const buildQuestionChips = (question: QaQuestionThreadQuestion, options: QaQuestionChipsOptions): Array<ComponentTypeWithSkeleton> => {
    const { isSkeleton, includeReplyCount } = options

    if (isSkeleton) {
        return [
            () => <Chip isSkeleton />,
            () => <Chip isSkeleton />,
        ]
    }

    const items: Array<ComponentTypeWithSkeleton> = [
        () => <Chip tone="default" text={scopeLabel(question.scope)} />,
        () => (
            <Chip
                tone={question.replyCount > 0 ? "success" : "default"}
                text={statusLabel(question.replyCount, question.answeredByFounder)}

            />
        ),
    ]

    if (includeReplyCount && question.replyCount > 0) {
        items.push(() => (
            <Typography
                size="xs"
                color="muted"
                text={`${question.replyCount} replies`}

            />
        ))
    }

    return items
}

/** Apply (or clear) a reaction pick against a `{count, myReaction}` pair, adjusting the count by exactly one. */
const applyReaction = (
    count: number,
    current: QaReactionType | null,
    next: QaReactionType | null,
): { count: number, myReaction: QaReactionType | null } => {
    if (current === next) {
        return { count, myReaction: current }
    }
    const delta = (next != null ? 1 : 0) - (current != null ? 1 : 0)
    return { count: Math.max(0, count + delta), myReaction: next }
}

/**
 * One course-Q&A conversation. See the file header for the full contract, the
 * assumed-sibling-contract risk, and the local-state judgement call.
 *
 * @param props - {@link QaQuestionThreadProps}
 */
const QaQuestionThread = ({
    question,
    currentUserId,
    currentUser,
    onAnswered,
    isSkeleton = false,
}: QaQuestionThreadProps) => {
    // Collapsed ⇄ Expanded is a real TOGGLE local to this instance, exactly like
    // `src`'s own `QuestionRow` (see file header) — never lifted to a prop.
    const [isExpanded, setIsExpanded] = useState(false)

    // Seeded ONCE from props — correct because this block is instantiated once per
    // question (`key={question.id}` at the call site remounts it on real data
    // change), same assumption `src`'s `QuestionRow` makes for its own local state.
    const [answers, setAnswers] = useState<ReadonlyArray<QaThreadAnswer>>(question.answers)
    const [questionReaction, setQuestionReaction] = useState({ count: question.reactionCount, myReaction: question.myReaction })
    const [draft, setDraft] = useState("")

    const isMineQuestion = currentUserId != null && currentUserId === question.author.id
    const askerDisplayName = isMineQuestion ? "You" : question.author.displayName

    // Distinct answerers → the "who joined in" avatar group in the header.
    const participants = useMemo<Array<QaQuestionThreadAuthor>>(() => {
        const seen = new Set<string>()
        const list: Array<QaQuestionThreadAuthor> = []
        for (const answer of answers) {
            if (!seen.has(answer.author.id)) {
                seen.add(answer.author.id)
                list.push(answer.author)
            }
        }
        return list
    }, [answers])

    const onReactQuestion = (type: QaReactionType | null) => {
        setQuestionReaction((prev) => applyReaction(prev.count, prev.myReaction, type))
    }

    const onReactAnswer = (answerId: string, type: QaReactionType | null) => {
        setAnswers((prev) => prev.map((answer) => {
            if (answer.id !== answerId) {
                return answer
            }
            const { count, myReaction } = applyReaction(answer.reactionCount, answer.myReaction, type)
            return { ...answer, reactionCount: count, myReaction }
        }))
    }

    const onAcceptAnswer = (answerId: string, accepted: boolean) => {
        setAnswers((prev) => prev.map((answer) => (answer.id === answerId ? { ...answer, isAcceptedAnswer: accepted } : answer)))
    }

    const canSubmitAnswer = draft.trim().length > 0 && currentUserId != null && currentUser != null

    const onSubmitAnswer = () => {
        if (!canSubmitAnswer || currentUserId == null || currentUser == null) {
            return
        }
        const newAnswer: QaThreadAnswer = {
            id: `local-${answers.length}-${Date.now()}`,
            body: draft.trim(),
            author: { id: currentUserId, displayName: currentUser.username, avatarUrl: currentUser.avatar },
            createdTimeAgo: "Just now",
            reactionCount: 0,
            myReaction: null,
        }
        setAnswers((prev) => [...prev, newAnswer])
        setDraft("")
        onAnswered?.()
    }

    // ── LEAF — Collapsed: a private social inbox row, the whole row pressable ──
    if (!isExpanded) {
        const askerNameRow = (
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                at="sm"
                align="center"
                isSkeleton={isSkeleton}

                items={[
                    () =>
                        isSkeleton ? (
                            <Typography size="xs" weight="medium" isSkeleton />
                        ) : (
                            <>
                                {question.isPinned ? (
                                    <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                                ) : null}
                                <Typography size="xs" weight="medium" text={askerDisplayName} />
                                {question.isFounderAuthor ? (
                                    <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                                ) : null}
                                <Typography size="xs" color="muted" text={`· ${question.createdTimeAgo}`} />
                            </>
                        ),
                ]}
            />
        )

        const questionPreview = isSkeleton ? (
            <StackV
                gap={2}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography size="sm" isSkeleton />,
                    () => <Typography size="sm" isSkeleton />,
                ]}
            />
        ) : (
            <MarkdownContent
                source={question.body}
                measure="compact"
                flow="embedded"
                previewLines={2}
            />
        )

        const previewColumn = (
            <FillAvailable
                at="base"
                isSkeleton={isSkeleton}
                body={() => (
                    <StackV
                        gap={2}
                        isSkeleton={isSkeleton}
                        items={[
                            () => askerNameRow,
                            () => questionPreview,
                            () => (
                                <Cluster
                                    gap={3}
                                    items={buildQuestionChips(question, { isSkeleton, includeReplyCount: true })}
                                />
                            ),
                        ]}
                    />
                )}
            />
        )

        const collapsedRow = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="start"
                isSkeleton={isSkeleton}

                items={[
                    () => (
                        <div>
                            <Avatar
                                src={question.author.avatarUrl}
                                name={question.author.displayName}
                                seed={question.author.id}
                                size="sm"
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    ),
                    () => previewColumn,
                    ...(!isSkeleton ? [() => (
                        <span
                            aria-hidden
                            className={cn("size-2 shrink-0 rounded-full", question.replyCount > 0 ? "bg-success" : "bg-warning")}
                        />
                    )] : []),
                ]}
            />
        )

        return (
            <div>
                <div>
                    <SurfaceCard
                        onPress={() => setIsExpanded(true)}
                        isDisabled={isSkeleton}

                        body={() => collapsedRow}
                    />
                </div>
            </div>
        )
    }

    // ── LEAF — Expanded: the full conversation ─────────────────────────────────
    const questionMetaRow = (
        <StackH
            gap={3}
            principle="identity"
            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}

            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" weight="medium" isSkeleton={isSkeleton} text={askerDisplayName} />,
                ...(question.isFounderAuthor ? [() => (
                    <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                )] : []),
                ...(question.isPinned ? [() => (
                    <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={question.createdTimeAgo} />,
            ]}
        />
    )

    const questionFooterRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <Cluster
                        gap={3}
                        items={buildQuestionChips(question, { isSkeleton: false, includeReplyCount: false })}

                    />
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <QaReactionBar
                        count={questionReaction.count}
                        myReaction={questionReaction.myReaction}
                        onReact={onReactQuestion}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // the question itself, as the first bubble of the conversation
    const questionBubble = (
        <div className={cn("flex w-full", isMineQuestion ? "justify-end" : "justify-start")}>
            <div className="max-w-[92%]">
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    align={isMineQuestion ? "end" : "stretch"}
                    classNames={["min-w-0"]}
                    isSkeleton={isSkeleton}

                    items={[
                        () => questionMetaRow,
                        ({ isSkeleton }: SkeletonProps) => (
                            <QaChatBubble role={isMineQuestion ? "user" : "assistant"} isSkeleton={isSkeleton}>
                                <MarkdownContent
                                    source={question.body}
                                    measure="compact"
                                    flow="embedded"
                                />
                            </QaChatBubble>
                        ),
                        () => questionFooterRow,
                    ]}
                />
            </div>
        </div>
    )

    // answers — QaMessageBubble recurses internally for flattened reply-to-reply
    const answerRows = answers.length === 0 ? (
        <Typography
            size="sm"
            color="muted"
            text="No answers yet — be the first."

        />
    ) : (
        answers.map((answer) => (
            <QaMessageBubble
                key={answer.id}
                answer={answer}
                currentUserId={currentUserId}
                canAccept={isMineQuestion}
                onAcceptAnswer={(accepted: boolean) => onAcceptAnswer(answer.id, accepted)}
                onReact={(type: QaReactionType | null) => onReactAnswer(answer.id, type)}

            />
        ))
    )

    const conversationBody = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={[
                () => questionBubble,
                () => answerRows,
            ]}
        />
    )

    const threadPanel = (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}

            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <QaConversationHeader
                        asker={{
                            id: question.author.id,
                            displayName: question.author.displayName,
                            avatarUrl: question.author.avatarUrl,
                        }}
                        isFounderAsker={question.isFounderAuthor}
                        participants={participants.map((p) => ({
                            id: p.id,
                            displayName: p.displayName,
                            avatarUrl: p.avatarUrl,
                        }))}
                        replyCount={question.replyCount}
                        onCollapse={() => setIsExpanded(false)}
                        isSkeleton={isSkeleton}

                    />
                ),
                () => conversationBody,
                // bottom composer — the only way to answer a course-general question
                ({ isSkeleton }: SkeletonProps) => (
                    <CourseQaComposer
                        mode="plain"
                        currentUser={currentUser ? { name: currentUser.username, avatarSrc: currentUser.avatar } : undefined}
                        value={draft}
                        onValueChange={setDraft}
                        onSubmit={onSubmitAnswer}
                        placeholder="Write your answer…"
                        submitLabel="Send"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard body={() => threadPanel} />
        </div>
    )
}

export { QaQuestionThread }

"use client"

import React from "react"
import { Tooltip } from "@heroui/react"
import type { ReactNode } from "react"
import { Chip, type ChipTone, type IconComponent } from "@/components/atoms/chips/Chip"

/** Soft-chip tones usable by an {@link EnumChip} (mirrors house {@link ChipTone}). */
export type EnumChipColor = ChipTone

/** One enum value's chip presentation. */
export interface EnumChipEntry {
    /** Soft chip tone. Omit to use the Chip default. */
    color?: EnumChipColor
    /** Visible label (already localized by the caller). */
    label: ReactNode
    /**
     * Optional leading icon — a component reference (`SiYoutube`), not a rendered
     * element. The house {@link Chip} atom mounts it at chip scale (contract E).
     */
    icon?: IconComponent
    /** Optional tooltip (already localized); wraps the chip in a Tooltip when set. */
    tooltip?: ReactNode
}

/** Props for {@link EnumChip}. */
export interface EnumChipProps<E extends string> {
    /** The current enum value; looked up in {@link map}. */
    value: E
    /**
     * Map from enum value to presentation. Usually declare it `Record<E, EnumChipEntry>`
     * at the call site to get TS completeness; the prop accepts `Partial` so a domain
     * may intentionally leave some values unhandled (they throw at render, matching the
     * old switch-`default`-throw behavior).
     */
    map: Partial<Record<E, EnumChipEntry>>
}

/**
 * Legacy block-tier "enum → soft chip" primitive still used by domain badges that pass
 * brand {@link IconComponent} refs (LessonVideoKindChip, HostPlatformChip). Appearance
 * lives on `entry.color`; no public className door. Prefer the composites `EnumChip`
 * when the leading glyph is a closed check/cross symbol.
 *
 * @param props - {@link EnumChipProps}
 */
export const EnumChip = <E extends string>({ value, map }: EnumChipProps<E>) => {
    const entry = map[value]
    if (!entry) {
        // exhaustive Record makes this unreachable in typed code; guards a bad runtime value
        throw new Error(`EnumChip: no map entry for value "${value}"`)
    }
    const chip = (
        <Chip
            tone={entry.color ?? "default"}
            text={entry.label}
            icon={entry.icon}
        />
    )
    if (entry.tooltip == null) {
        return chip
    }
    return (
        <Tooltip>
            <Tooltip.Trigger>{chip}</Tooltip.Trigger>
            <Tooltip.Content>{entry.tooltip}</Tooltip.Content>
        </Tooltip>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@heroui/react"
import type { IconComponent } from "@/components/atoms/chips/Chip"
import { ElementCloseButton } from "@/components/blocks/buttons/ElementCloseButton"

/**
 * Semantic tone of the status chip. Each tone maps to a HeroUI Chip color
 * (the neutral tone maps to the default color).
 */
export type StatusChipTone = "neutral" | "success" | "warning" | "danger" | "accent"

/**
 * Props for the {@link StatusChip} block.
 *
 * Does NOT take `className` (BLOCK-4 — a block hands out no escape hatch; a
 * caller that needs a specific placement uses a frame, not a hole in this
 * component). `icon` is an {@link IconComponent} reference this block mounts
 * at chip scale (contract E).
 */
export interface StatusChipProps {
    /**
     * Semantic tone that drives the chip color. Defaults to "neutral".
     */
    tone?: StatusChipTone
    /**
     * Optional leading icon — a component reference (`CheckCircleIcon`), not a
     * rendered element. This block mounts it at `size-4`. When {@link onCancel}
     * is set, the leading icon is dropped (removable chips carry a trailing ×
     * instead).
     */
    icon?: IconComponent
    /**
     * Label content rendered inside the chip.
     */
    children: ReactNode
    /**
     * When provided, renders a TRAILING cancel button (X at the end) — click it to
     * remove/cancel the chip. Uses HeroUI `CloseButton` with its OWN default × glyph
     * (per `alert.md`: close-affordances use `CloseButton`, never a hand-rolled
     * `<button><XIcon/>` — and don't override its glyph either; same treatment as
     * `Callout`). When set, the leading {@link StatusChipProps.icon} is DROPPED — a
     * removable/filter chip carries EITHER a leading status icon OR a trailing
     * cancel-X, never both (teacher: "once there's an X, there's no prefix icon").
     */
    onCancel?: () => void
    /**
     * Accessible label for the cancel button (the caller passes a localised string,
     * e.g. `t("common.remove")`). Falls back to HeroUI's default "Close".
     */
    cancelLabel?: string
}

/**
 * Maps a {@link StatusChipTone} to the matching HeroUI Chip color.
 */
const toneToColor: Record<StatusChipTone, "default" | "success" | "warning" | "danger" | "accent"> = {
    neutral: "default",
    success: "success",
    warning: "warning",
    danger: "danger",
    accent: "accent",
}

/**
 * Generic, presentational status chip. A thin pill-shaped wrapper over the
 * HeroUI Chip that maps a semantic tone to a chip color and optionally mounts a
 * leading {@link IconComponent} before the label. Presentational: the only
 * callback it takes is {@link StatusChipProps.onCancel} for a removable/filter
 * chip (a trailing cancel-X).
 *
 * Root stays raw HeroUI `Chip` rather than the design system's `Chip` atom so
 * {@link ElementCloseButton} can keep tonal cancel styling on the removable
 * branch without splitting close-affordance implementations.
 *
 * Does not take `className` (BLOCK-4) — a caller that needs a specific
 * placement composes a frame (`StackH`/`Cluster`/…) around the chip instead.
 * @see Story: .storybook/stories/blocks/chips/StatusChip/StatusChip.stories
 */
export const StatusChip = ({
    tone = "neutral",
    icon: Icon,
    children,
    onCancel,
    cancelLabel,
}: StatusChipProps) => {
    return (
        <Chip
            data-tier="block"
            data-component="StatusChip"
            color={toneToColor[tone]}
            variant="soft"
            size="sm"
            // w-fit: a chip is a hug-content pill by default — an explicit width
            // defeats a parent flex-col's `align-items: stretch` so it never
            // gets stretched full-width (card family §chip). Icon forced to
            // size-4 so every chip icon reads uniformly regardless of caller.
            // Colour is HeroUI's NATIVE soft pairing (`--chip-bg`=`<color>-soft`,
            // `--chip-fg`=`<color>-soft-foreground`) — no hand-rolled tint, so the
            // label + icon inherit an accessibility-tuned foreground (the old
            // `bg-<status>/10 + text-<status>` raw-hue formula failed contrast).
            className="w-fit"
        >
            {/* leading status icon — DROPPED when the chip is removable (has a
                trailing cancel-X): a chip carries EITHER a status icon OR a cancel-X,
                never both. Icon forced to size-4 so it reads uniformly. */}
            {Icon && !onCancel ? (
                <Icon className="size-4 shrink-0" aria-hidden focusable="false" />
            ) : null}
            <Chip.Label>{children}</Chip.Label>
            {onCancel ? (
                // shared close × — bakes transparent-at-rest + tonal hover (same
                // treatment as Callout's dismiss). `tone={tone}` so the X + its hover
                // read the chip's own colour, not a foreign grey.
                <ElementCloseButton
                    label={cancelLabel ?? ""}
                    onPress={onCancel}
                    tone={tone}
                />
            ) : null}
        </Chip>
    )
}

import React from "react"
import { Typography } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { ReactionBar } from "../ReactionBar"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for {@link _CommunityCommentRow} — presentational; labels already resolved. */
export interface CommunityCommentRowProps {
    /** The comment to render. */
    comment: QueryCommunityCommentNode
    /**
     * React handler — pass the chosen emotion, or `null` to remove. Omit to render
     * the reaction bar READ-ONLY (e.g. when the viewer is signed out).
     */
    onReact?: (type: ReactionType | null) => void
    /**
     * Optional actions rendered below the body (e.g. reply / view-replies controls).
     * Supplied by the owning feature so the row stays presentational.
     */
    actions?: React.ReactNode
    /** Already-localized placeholder shown instead of the body when the comment is soft-deleted. */
    deletedLabel: string
    /** Already-localized relative "x minutes ago" timestamp. */
    timeAgoLabel: string
}

/**
 * One community comment row: avatar + author (with founder badge) + relative time,
 * the markdown body, a reaction bar, and an optional actions slot. Pure block:
 * owns its look; the owning feature supplies data + the react handler + actions.
 *
 * @param props - {@link CommunityCommentRowProps}
 */
export const _CommunityCommentRow = ({
    comment,
    onReact,
    actions,
    deletedLabel,
    timeAgoLabel,
}: CommunityCommentRowProps) => {
    // resolve the display name, falling back to the username when unset
    const displayName = comment.author.displayName || comment.author.username

    // Soft-deleted comments are still returned by the listing (BE does not filter
    // `isDeleted`); render a muted placeholder instead of the (empty) body, and
    // suppress author identity, the reaction bar, and reply/edit controls. The
    // `actions` slot is still rendered so thread navigation (e.g. "view replies")
    // the owning feature chooses to keep stays reachable on a deleted node.
    if (comment.isDeleted) {
        return (
            <div>
                <div className="flex min-w-0 flex-col gap-1">
                    <Typography type="body-xs" color="muted" className="italic">
                        {deletedLabel}
                    </Typography>
                    {actions ? (
                        <div className="flex items-center gap-3">{actions}</div>
                    ) : null}
                </div>
            </div>
        )
    }

    return (
        <div>
            <div className="flex gap-3">
                <UserAvatar
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                />
                <div className="flex min-w-0 flex-1 flex-col gap-1">
                    <div className="flex items-center gap-1">
                        <Typography type="body-xs" weight="semibold" truncate>
                            {displayName}
                        </Typography>
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <Typography type="body-xs" color="muted">
                            {timeAgoLabel}
                        </Typography>
                    </div>
                    <MarkdownContent markdown={comment.body} flow="embedded" />
                    <div className="flex items-center gap-3">
                        <ReactionBar
                            count={comment.reactions.total}
                            myReaction={comment.reactions.myReaction}
                            onReact={onReact}
                        />
                        {actions}
                    </div>
                </div>
            </div>
        </div>
    )
}

