"use client"

import React, { useCallback, useMemo, useState } from "react"
import { Chip, Link, Spinner, cn } from "@heroui/react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { ReactionBar } from "@/components/blocks/community/Discussion/ReactionBar"
import { QaInboxRow } from "../QaInboxRow"
import { QaConversationHeader, type QaConversationHeaderPerson } from "../QaConversationHeader"
import { QaMessageBubble } from "../QaMessageBubble"
import { useQuestionAnswers } from "@/hooks/swr/api/graphql/queries/useQuestionAnswersSwr"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link QaQuestionThread}. */
export interface QaQuestionThreadProps {
    /** The question to render. */
    question: CourseQuestionNode
    /** Current viewer id (drives own-bubble alignment + owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the answer composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Called after an answer is posted/edited/deleted — bumps the parent roll-up's aggregates. */
    onAnswered?: () => void
}

/**
 * One course-Q&A conversation. Collapsed, it is a social {@link QaInboxRow} (asker,
 * preview, scope tag, answered/unanswered status, reply count, status dot). Pressing
 * it expands the FULL conversation inline: a {@link QaConversationHeader} (asker +
 * who-joined-in avatar group), the question itself rendered as the first chat bubble
 * (with its lesson-funnel tag + status), then every answer as a {@link QaMessageBubble}
 * — the viewer's own messages align right, peers + founder align left — and a
 * bottom {@link Composer} to add an answer. This is the ONLY place to answer a
 * course-general question (it has no lesson page of its own).
 *
 * Owns the expand state + the answer thread's data/persistence (via
 * {@link useQuestionAnswers}, gated on `expanded` so nothing fetches until opened).
 *
 * @param props - {@link QaQuestionThreadProps}
 */
export const QaQuestionThread = ({ question, currentUserId, currentUser, onAnswered}: QaQuestionThreadProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // display id (slug) builds the lesson route the question's tag links to
    const displayId = useAppSelector((state) => state.course.displayId)

    // answer-thread toggle; the answers are gated on `expanded` inside the facade hook,
    // so opening the conversation the first time is what triggers the fetch
    const [expanded, setExpanded] = useState(false)
    // draft + in-flight guard for the bottom "add an answer" composer
    const [answerDraft, setAnswerDraft] = useState("")
    const [isPostingAnswer, setIsPostingAnswer] = useState(false)

    const {
        answers,
        isLoadingAnswers,
        answerRepliesByParent,
        onReply,
        onEdit,
        onDelete,
        onReactComment,
        onReactQuestion,
        onAcceptAnswer,
        onLoadReplies,
    } = useQuestionAnswers(question.id, expanded, onAnswered)

    const isMineQuestion = currentUserId !== null && currentUserId === question.author.id
    const questionName = isMineQuestion ? t("courseQa.you") : (question.author.displayName || question.author.username)

    // follow the asker — local optimistic state seeded from the server flag; only the
    // viewer's own toggle mutates it, so no re-sync on list refetch is needed
    const { trigger: triggerSetFollow, isMutating: isFollowPending } = useMutateSetFollowSwr()
    const [isFollowingAsker, setIsFollowingAsker] = useState(question.author.isFollowedByMe)
    // never follow yourself; hide the control when signed out or on your own question
    const canFollowAsker = currentUserId !== null && currentUserId !== question.author.id
    const onToggleFollow = useCallback(async () => {
        const next = !isFollowingAsker
        const result = await triggerSetFollow({ userId: question.author.id, follow: next })
        // commit only on a confirmed success (mirrors the league board's follow flow)
        if (result?.data?.setFollow?.success) {
            setIsFollowingAsker(next)
        }
    }, [isFollowingAsker, triggerSetFollow, question.author.id])

    // distinct answerers → the "who joined in" avatar group in the header
    const participants = useMemo<Array<QaConversationHeaderPerson>>(() => {
        const seen = new Set<string>()
        const list: Array<QaConversationHeaderPerson> = []
        for (const answer of answers) {
            if (!seen.has(answer.author.id)) {
                seen.add(answer.author.id)
                list.push({
                    id: answer.author.id,
                    displayName: answer.author.username,
                    avatarUrl: answer.author.avatar ?? undefined,
                })
            }
        }
        return list
    }, [answers])

    /**
     * Route to the source lesson — the funnel back into the course content. A no-op
     * for a course-general question (no `contentId`/`moduleId` to route to).
     */
    const goToLesson = useCallback(() => {
        if (!displayId || !question.contentId || !question.moduleId) {
            return
        }
        router.push(
            pathConfig()
                .locale(locale)
                .course(displayId)
                .learn()
                .module(question.moduleId)
                .content(question.contentId)
                .build(),
        )
    }, [displayId, locale, router, question.contentId, question.moduleId])

    /** Post a new top-level answer via the bottom composer, then clear the draft. */
    const submitAnswer = useCallback(async () => {
        const body = answerDraft.trim()
        if (!body) {
            return
        }
        setIsPostingAnswer(true)
        try {
            await onReply(question.id, body)
            setAnswerDraft("")
        } finally {
            setIsPostingAnswer(false)
        }
    }, [answerDraft, onReply, question.id])

    // collapsed — a flush social inbox row inside the parent's SurfaceListCard
    if (!expanded) {
        return (
            <QaInboxRow
                question={question}
                onOpen={() => setExpanded(true)}
            />
        )
    }

    // expanded — the full conversation, rendered inline in place of the row
    return (
        <div className={"flex flex-col gap-4 p-3"}>
            <QaConversationHeader
                asker={{
                    id: question.author.id,
                    displayName: question.author.displayName || question.author.username,
                    avatarUrl: question.author.avatar ?? undefined,
                }}
                isFounderAsker={question.isFounderAuthor}
                participants={participants}
                replyCount={question.replyCount}
                onCollapse={() => setExpanded(false)}
                canFollow={canFollowAsker}
                isFollowing={isFollowingAsker}
                onToggleFollow={() => { void onToggleFollow() }}
                isFollowPending={isFollowPending}
            />

            <div className="flex flex-col gap-4">
                {/* the question itself, as the first bubble of the conversation */}
                <div className={cn("flex w-full", isMineQuestion ? "justify-end" : "justify-start")}>
                    <div className={cn("flex min-w-0 max-w-[92%] flex-col gap-1", isMineQuestion && "items-end")}>
                        <div className="flex flex-wrap items-center gap-2 px-1 text-xs text-muted">
                            <span className="font-medium text-foreground">{questionName}</span>
                            {question.isFounderAuthor ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.founderBadge")}
                                </span>
                            ) : null}
                            {question.isPinned ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <PushPinIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.pinned")}
                                </span>
                            ) : null}
                            <span>{getTimeAgoLabel(getTimeAgoMessage(question.createdAt), t)}</span>
                        </div>

                        <ChatBubble role={isMineQuestion ? "user" : "assistant"}>
                            <MarkdownContent markdown={question.body} density="compact" flow="embedded" />
                        </ChatBubble>

                        {/* lesson-funnel tag (course content) + answered/unanswered status */}
                        <div className={cn("flex flex-wrap items-center gap-2 px-1", isMineQuestion && "flex-row-reverse")}>
                            {question.contentId ? (
                                <Link onPress={goToLesson} className="cursor-pointer no-underline">
                                    <Chip
                                        size="sm"
                                        variant="soft"
                                        className="bg-default text-muted transition-colors hover:text-foreground"
                                    >
                                        {t("courseQa.lessonTag", { title: question.contentTitle ?? "" })}
                                    </Chip>
                                </Link>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.generalTag")}
                                </Chip>
                            )}
                            {question.replyCount > 0 ? (
                                <Chip size="sm" variant="soft" color="success" className="gap-1">
                                    {question.answeredByFounder ? (
                                        <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    ) : null}
                                    {question.answeredByFounder
                                        ? t("courseQa.answeredByFounder")
                                        : t("courseQa.statusAnswered")}
                                </Chip>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.statusUnanswered")}
                                </Chip>
                            )}
                            {/* react to the question itself (6-emotion) — the question is a comment */}
                            <ReactionBar
                                summary={question.reactions}
                                onReact={(type) => { void onReactQuestion(type) }}
                            />
                        </div>
                    </div>
                </div>

                {/* answers — each a chat bubble; own messages right, peers + founder left */}
                {isLoadingAnswers && answers.length === 0 ? (
                    <div className="flex justify-center py-2">
                        <Spinner size="sm" />
                    </div>
                ) : (
                    answers.map((answer) => (
                        <QaMessageBubble
                            key={answer.id}
                            comment={answer}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            repliesByParent={answerRepliesByParent}
                            // only the asker may accept, and only a DIRECT answer (this map)
                            canAccept={isMineQuestion}
                            onAcceptAnswer={(commentId, accepted) => { void onAcceptAnswer(commentId, accepted) }}
                            onReply={(parentId, body) => { void onReply(parentId, body) }}
                            onEdit={(commentId, body) => { void onEdit(commentId, body) }}
                            onDelete={(commentId) => { void onDelete(commentId) }}
                            onReactComment={(commentId, type) => { void onReactComment(commentId, type) }}
                            onLoadReplies={onLoadReplies}
                        />
                    ))
                )}
            </div>

            {/* bottom composer — add an answer as a chat message */}
            <Composer
                value={answerDraft}
                onChange={setAnswerDraft}
                onSubmit={() => { void submitAnswer() }}
                isSubmitting={isPostingAnswer}
                avatarSrc={currentUser?.avatar}
                placeholder={t("discussion.replyPlaceholder")}
                submitLabel={t("discussion.reply")}
            />
        </div>
    )
}

"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@/components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@/components/atoms/text/Typography"
import { DragScrollArea } from "@/components/behaviors/DragScrollArea"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { NavigationRail } from "@/components/frames/NavigationRail"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `CollapsibleSidebar` — a content-agnostic shell for a left navigation sidebar
 * that collapses in place (no overlay/Drawer). Owns collapse/expand, the width
 * animation, persisting the choice to `localStorage`, and a `useSidebarCollapsed`
 * context so nav-row content can self-adapt to the icon-only rail. It never
 * inspects `children`. One leaf: `topSlot` presence and the collapsed flag are
 * data, so they are states, not separate leaves.
 */

/** Expanded panel width (full nav). */
const EXPANDED_WIDTH = "16rem"
/** Collapsed rail width — fits a centered icon row + the toggle. */
const COLLAPSED_WIDTH = "4rem"

/**
 * Named transition shapes (not inline object literals at the call site — check-inline-types
 * gate) for the width animation: a spring when motion is welcome, instant when the reader (or
 * their OS) asked for reduced motion.
 */
const SPRING_TRANSITION = { type: "spring" as const, stiffness: 420, damping: 38 }
const INSTANT_TRANSITION = { duration: 0 }
/** Title fade — quick cross-fade, same instant fallback under reduced motion. */
const FADE_TRANSITION = { duration: 0.15 }

/**
 * Collapsed flag shared with nav-row children so a row can drop to icon-only in
 * the rail. Internal UI chrome state — not an app store.
 */
const SidebarCollapsedContext = createContext(false)

/** Read whether the surrounding {@link CollapsibleSidebar} is collapsed (icon-rail). */
export const useSidebarCollapsed = (): boolean => useContext(SidebarCollapsedContext)

/** Props for the {@link CollapsibleSidebar} composite. */
export interface CollapsibleSidebarProps {
    /** Heading shown in the panel header (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /**
     * Stable key under which the collapsed flag persists in `localStorage`, so
     * the choice survives navigation between pages that share this sidebar.
     */
    storageKey: string
    /**
     * Optional node pinned BETWEEN the header and the scrollable nav — always
     * visible (outside the scroll area). Rendered inside the collapsed-context
     * provider, so it can adapt to the rail (e.g. a resume pill → play icon).
     */
    topSlot?: ReactNode
    /** The panel body — nav rows/groups; content-agnostic, this shell never inspects them. */
    children: ReactNode
    /**
     * Placement utilities only. Retained while forbidden mia-mia consumers still
     * pass a height/layout class; StarCi callers should prefer parent frames.
     */
    className?: string
}

/**
 * A left navigation sidebar that collapses IN PLACE: the panel animates between
 * a full {@link EXPANDED_WIDTH} (title + nav) and a thin {@link COLLAPSED_WIDTH}
 * rail (just the toggle), and the surrounding content reflows beside it — no
 * overlay/Drawer. Self-contained: the collapsed state is local UI chrome,
 * hydrated from storage on mount (SSR-safe — starts expanded, then syncs).
 *
 * @param props - {@link CollapsibleSidebarProps}
 */
export const CollapsibleSidebar = ({
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    children,
    className,
}: CollapsibleSidebarProps) => {
    const reduceMotion = useReducedMotion()
    const [collapsed, setCollapsed] = useState(false)

    // hydrate the persisted choice after mount (avoids SSR/client mismatch)
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored !== null) {
            setCollapsed(stored === "true")
        }
    }, [storageKey])

    /** Flip + persist the collapsed flag. */
    const toggle = () => {
        setCollapsed((prev) => {
            const next = !prev
            window.localStorage.setItem(storageKey, String(next))
            return next
        })
    }

    // §10a: the vertical rhythm between header / topSlot / nav is owned by THIS
    // StackV's gap — no section carries its own margin (a prior draft put
    // `mb-6` on the header row itself, flagged by check-padding as a second
    // owner for the same seam).
    return (
        <SidebarCollapsedContext.Provider value={collapsed}>
            <motion.aside

                initial={false}
                animate={{ width: collapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
                transition={reduceMotion ? INSTANT_TRANSITION : SPRING_TRANSITION}
                className={cn(
                    // ONE padding wrapper for the whole rail: p-6 expanded / px-3 py-6
                    // collapsed. No frame in this tree types an asymmetric inset, so this
                    // stays hand-written on the composite's own bespoke root (§13c precedent:
                    // Toolbar/ModalShell/DrawerShell do the same on theirs).
                    "flex h-full shrink-0 overflow-hidden border-r border-default",
                    collapsed ? "px-3 py-6" : "p-6",
                    className,
                )}
            >
                <StackV
                    identity={{ tier: "block", component: "CollapsibleSidebar" }}
                    gap={6}
                    classNames={["min-h-0", "flex-1"]}
                    principle="group-boundary"
                    explain="Separates header, pinned top slot, and scrollable nav so each region keeps its own seam owner — not sibling-stack, because these are distinct section roles rather than repeating peers."
                    items={[
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                justify={collapsed ? "center" : "between"}
                                items={[
                                    () => (
                                        <AnimatePresence initial={false}>
                                            {!collapsed ? (
                                                <motion.div
                                                    key="title"
                                                    initial={{ opacity: 0 }}
                                                    animate={{ opacity: 1 }}
                                                    exit={{ opacity: 0 }}
                                                    transition={reduceMotion ? INSTANT_TRANSITION : FADE_TRANSITION}
                                                    className="min-w-0"
                                                >
                                                    <Typography
                                                        size="h5"
                                                        weight="bold"
                                                        truncate
                                                        text={title}
                                                    />
                                                </motion.div>
                                            ) : null}
                                        </AnimatePresence>
                                    ),
                                    () => (
                                        <ButtonBase
                                            isIconOnly
                                            variant="ghost"
                                            size="sm"
                                            ariaLabel={collapsed ? expandLabel : collapseLabel}
                                            prefixIcon={SidebarSimpleIcon}
                                            onPress={toggle}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        // pinned top slot (e.g. resume pill) — above the scroll area, always
                        // visible. min-w-0: a column-flex item defaults to content-width
                        // (min-width: auto), which would let it overflow the rail and get
                        // hard-clipped by overflow-hidden instead of shrinking so its own
                        // `truncate` text can ellipsize.
                        () => (
                            <FillAvailable
                                at="base"
                                body={() => <>{topSlot}</>}
                            />
                        ),
                        // body: the nav — ALWAYS rendered; row content decides its own icon-only
                        // look off `useSidebarCollapsed`. `NavigationRail` owns the `<nav>`
                        // landmark + column flex-fill; `DragScrollArea` owns the overflow
                        // (hidden scrollbar + Windows-safe pointer-pan); inner `StackV` gives
                        // the column its `gap={4}` rhythm and default `align="stretch"` (rows
                        // fill the rail's width whether expanded or collapsed).
                        () => (
                            <NavigationRail
                                body={() => (
                                    <DragScrollArea size={40} className="flex-1">
                                        <StackV
                                            gap={4}
                                            principle="sibling-stack"
                                            explain="Same-kind peer stack of nav rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                            items={[() => children]}
                                        />
                                    </DragScrollArea>
                                )}
                            />
                        ),
                    ]}
                />
            </motion.aside>
        </SidebarCollapsedContext.Provider>
    )
}

import React, { useMemo } from "react"
import ReactMarkdown from "react-markdown"
import remarkGfm from "remark-gfm"
import remarkDirective from "remark-directive"
import { cn } from "@heroui/react"
import type { Components } from "react-markdown"
// Re-export the colocated sub-renderers so the reuseable barrel surface stays identical.
export * from "./CodeToHtml"
export * from "./LayoutWidget"
export * from "./MermaidDiagram"

/**
 * Recursively rewrites `:::muted` directives (container/leaf/text, parsed by `remark-directive`)
 * into custom hast tags the renderer map styles as small muted text. Container/leaf → block-level
 * `mutedblock`; inline `:muted[…]` → `mutedtext`. Directives with any other name are left untouched
 * (and dropped by the hast conversion since they have no handler).
 * @param node - Current mdast node being walked.
 */
const applyMutedDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (
        (node.type === "containerDirective" || node.type === "leafDirective" || node.type === "textDirective")
        && node.name === "muted"
    ) {
        const data = node.data || (node.data = {})
        data.hName = node.type === "textDirective" ? "mutedtext" : "mutedblock"
        data.hProperties = {}
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyMutedDirective(child as Parameters<typeof applyMutedDirective>[0])
        }
    }
}

/** remark transformer: turn `:::muted` directives into styled custom tags. */
const remarkMuted = () => (tree: unknown): void => {
    applyMutedDirective(tree as Parameters<typeof applyMutedDirective>[0])
}

/**
 * Recursively rewrites the `:::tab` / `:::code` / `:::preview` container directives into custom hast
 * tags the renderer map turns into a [Preview|Code] tabs block (see TabsBlock): `tab`→`tabblock`,
 * `code`→`tabcode`, `preview`→`tabpreview`. Each pane's child fence (` ```tsx ` / ` ```mdx `) still
 * renders through the normal `pre` handler. Other directive names are left untouched.
 *
 * Note: container nesting needs MORE colons on the outer fence — `::::tab` wraps `:::code` /
 * `:::preview`.
 * @param node - Current mdast node being walked.
 */
const applyTabDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        const tag = node.name === "tab"
            ? "tabblock"
            : node.name === "code"
                ? "tabcode"
                : node.name === "preview"
                    ? "tabpreview"
                    : null
        if (tag) {
            const data = node.data || (node.data = {})
            data.hName = tag
            data.hProperties = {}
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyTabDirective(child as Parameters<typeof applyTabDirective>[0])
        }
    }
}

/** remark transformer: turn `::::tab`/`:::code`/`:::preview` directives into tabs-block tags. */
const remarkTab = () => (tree: unknown): void => {
    applyTabDirective(tree as Parameters<typeof applyTabDirective>[0])
}

/**
 * Recursively collects the raw text of a directive subtree, preserving line breaks so each
 * authored line (one keyword per line) can be split back out into a separate chip.
 * @param node - Current mdast node.
 */
const collectDirectiveText = (node: { type?: string, value?: string, children?: Array<unknown> }): string => {
    if (node.type === "text") {
        return node.value ?? ""
    }
    if (node.type === "break") {
        return "\n"
    }
    if (Array.isArray(node.children)) {
        return node.children
            .map((child) => collectDirectiveText(child as Parameters<typeof collectDirectiveText>[0]))
            .join("\n")
    }
    return ""
}

/**
 * Rewrites the `:::chip` container directive into a custom `chipblock` tag (see map.tsx),
 * carrying its keywords (one per authored line) as a newline-split, `|`-joined `items` prop so the
 * renderer can render each as its own Chip. Other directive names are left untouched.
 * @param node - Current mdast node being walked.
 */
const applyChipDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective" && node.name === "chip") {
        const items = collectDirectiveText(node)
            .split(/[\n·]+/)
            .map((line) => line.trim())
            .filter((line) => line.length > 0)
        const data = node.data || (node.data = {})
        data.hName = "chipblock"
        data.hProperties = {
            items: items.join("|"),
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyChipDirective(child as Parameters<typeof applyChipDirective>[0])
        }
    }
}

/** remark transformer: turn `:::chip` directives into a chips-row tag. */
const remarkChip = () => (tree: unknown): void => {
    applyChipDirective(tree as Parameters<typeof applyChipDirective>[0])
}

/**
 * Recursively rewrites the `::::accordion` / `:::panel` container directives into custom hast tags the
 * renderer map turns into a HeroUI Accordion (see map.tsx): `accordion`→`accordionblock`; each
 * `:::panel{title="…"}`→`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence — `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: { type?: string, name?: string, attributes?: Record<string, string>, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
        } else if (node.name === "panel") {
            const data = node.data || (node.data = {})
            data.hName = "accordionpanel"
            data.hProperties = {
                title: node.attributes?.title ?? "",
            }
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyAccordionDirective(child as Parameters<typeof applyAccordionDirective>[0])
        }
    }
}

/** remark transformer: turn `::::accordion`/`:::panel` directives into accordion tags. */
const remarkAccordion = () => (tree: unknown): void => {
    applyAccordionDirective(tree as Parameters<typeof applyAccordionDirective>[0])
}

/**
 * True for a `:::muted` directive node — already tagged `hName: "mutedblock"` by
 * {@link remarkMuted}. Its OWN content shape then decides how {@link groupArcSections}
 * handles it — see {@link isSelfContainedLeadBoldMuted} / {@link isBareLabelMuted}.
 * @param node - Current mdast node.
 */
const isMutedLabelNode = (node: { data?: { hName?: unknown } }): boolean => node.data?.hName === "mutedblock"

/**
 * True for the actual authoring idiom found in the card catalog: ONE paragraph
 * that OPENS with a `**bold**` span and keeps going as prose on the same line/block
 * (`**Solution** — NestJS provides three hooks...`) — label and body live in the SAME
 * mdast paragraph node. Two places this shape shows up: as a bare top-level
 * paragraph, OR (the actual catalog convention) as the sole child of a `:::muted`
 * directive — see {@link isSelfContainedLeadBoldMuted}.
 * @param node - Current mdast node.
 */
const isLeadBoldParagraph = (node: { type?: string, children?: Array<{ type?: string }> }): boolean =>
    node.type === "paragraph"
    && Array.isArray(node.children)
    && node.children.length > 0
    && node.children[0]?.type === "strong"

/**
 * True when a `:::muted` directive's ENTIRE content is one {@link isLeadBoldParagraph}
 * — the real catalog shape (`:::muted\n**Solution** — NestJS provides...\n:::`),
 * where the directive is a pointless extra wrapper around an already-self-contained
 * section. {@link groupArcSections} unwraps it (tags the inner paragraph directly)
 * instead of double-wrapping, which is what caused the infinite recursion this fixes
 * — re-processing a wrapper whose only child is still `hName: "mutedblock"` kept
 * re-matching {@link isMutedLabelNode} forever.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isSelfContainedLeadBoldMuted = (node: { children?: Array<{ type?: string, children?: Array<{ type?: string }> }> }): boolean =>
    Array.isArray(node.children) && node.children.length === 1 && isLeadBoldParagraph(node.children[0])

/**
 * True when a `:::muted` directive's ENTIRE content is ONE short inline node (the
 * doc-documented shape: `:::muted\n<Label>\n:::\n<body>` — label alone, body
 * follows as an external sibling). {@link groupArcSections} wraps this shape and
 * absorbs the following siblings as its body, unlike {@link isSelfContainedLeadBoldMuted}
 * which already has its body inside.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isBareLabelMuted = (node: { children?: Array<{ type?: string, children?: Array<unknown> }> }): boolean => {
    const only = node.children?.[0]
    return Array.isArray(node.children) && node.children.length === 1
        && only?.type === "paragraph"
        && Array.isArray(only.children) && only.children.length === 1
}

/**
 * Turns each Interview Arc section into one `arcsection` node so the renderer
 * (`map.tsx`) can box/collapse a whole "label + body" unit instead of rendering it
 * as flat, undifferentiated siblings/prose. Three authoring shapes exist in the card
 * catalog and are handled differently:
 * - `:::muted` wrapping a lead-bold paragraph (see {@link isSelfContainedLeadBoldMuted},
 *   the actual catalog convention) — the directive is unwrapped; its inner paragraph
 *   is retagged directly.
 * - Bare `:::muted` label (see {@link isBareLabelMuted}, the shape documented in
 *   `.claude/docs/rules/flashcard-answer.md` §2) — wrapped, absorbing every sibling
 *   that follows up to the next label as its body.
 * - Bare lead-bold paragraph, no `:::muted` at all — retagged in place.
 * Every node this function tags or wraps is added to `skip` so the second pass never
 * re-descends into it — re-visiting a `hName: "mutedblock"` node nested one level
 * inside its own freshly-created wrapper is what caused unbounded recursion before
 * this fix (a single-child wrapper around a still-muted-tagged node kept re-matching
 * and re-wrapping itself forever). Each `arcsection` carries its position (`index`,
 * 0-based) so the renderer can keep the first two sections (TL;DR / mechanism) always
 * expanded and collapse the rest behind a chip — the fixed order documented in
 * `.claude/docs/rules/flashcard-answer.md` §2.
 * @param node - Current mdast node being walked.
 */
const groupArcSections = (node: { children?: Array<Record<string, unknown>> }): void => {
    if (!Array.isArray(node.children)) {
        return
    }
    const grouped: Array<Record<string, unknown>> = []
    let current: { type: string, children: Array<unknown>, data: Record<string, unknown> } | null = null
    let sectionIndex = 0
    const skip = new Set<unknown>()
    for (const child of node.children) {
        if (isMutedLabelNode(child as Parameters<typeof isMutedLabelNode>[0])) {
            if (isSelfContainedLeadBoldMuted(child as Parameters<typeof isSelfContainedLeadBoldMuted>[0])) {
                const inner = (child.children as Array<Record<string, unknown>>)[0]
                const data = (inner.data as Record<string, unknown>) || (inner.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(inner)
                skip.add(inner)
            } else if (isBareLabelMuted(child as Parameters<typeof isBareLabelMuted>[0])) {
                current = {
                    type: "arcSection",
                    children: [child],
                    data: { hName: "arcsection", hProperties: { index: sectionIndex } },
                }
                sectionIndex += 1
                grouped.push(current)
                skip.add(current)
            } else {
                // muted content that's neither shape (multi-paragraph, code block…) —
                // tag the directive itself as one section, keep its children as-is.
                const data = (child.data as Record<string, unknown>) || (child.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(child)
                skip.add(child)
            }
        } else if (isLeadBoldParagraph(child as Parameters<typeof isLeadBoldParagraph>[0])) {
            const data = (child.data as Record<string, unknown>) || (child.data = {})
            data.hName = "arcsection"
            data.hProperties = { index: sectionIndex }
            sectionIndex += 1
            current = null
            grouped.push(child)
            skip.add(child)
        } else if (current) {
            current.children.push(child)
        } else {
            grouped.push(child)
        }
    }
    node.children = grouped
    for (const child of node.children) {
        if (skip.has(child)) {
            continue
        }
        groupArcSections(child as Parameters<typeof groupArcSections>[0])
    }
}

/** remark transformer: box each Interview Arc label + its following body into one `arcsection`. */
const remarkArcSections = () => (tree: unknown): void => {
    groupArcSections(tree as Parameters<typeof groupArcSections>[0])
}

/**
 * Module-level constant — NOT recreated every render. If `remarkPlugins={[...]}` were inline, each
 * MarkdownContent re-render would hand ReactMarkdown a new array → re-parse the whole markdown.
 */
const REMARK_PLUGINS = [remarkGfm, remarkDirective, remarkMuted, remarkTab, remarkChip, remarkAccordion]
// Opt-in variant (flashcard/mock-interview answers, see `arcSections` prop) — same
// stable module-level array so ReactMarkdown never sees a fresh array identity.
const REMARK_PLUGINS_ARC = [...REMARK_PLUGINS, remarkArcSections]

// Matches each ```mermaid fence and the figure caption paragraph that follows it.
// Group 1 = diagram source; group 2 = the first non-blank line after the fence.
const MERMAID_CAPTION_REGEX = /```mermaid[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*\r?\n+[ \t]*([^\r\n]+)/g

/**
 * Cuts off a trailing ```mermaid fence that hasn't been closed yet — markdown fed in
 * progressively (the mock-interview typewriter reveal, an AI stream) walks THROUGH every
 * partial length of the diagram source one tick at a time, and `mermaid.render()` throws
 * "Syntax error in text" for every one of those incomplete snapshots. Since a reveal only
 * ever GROWS the text, at most the LAST fence can be unterminated — any earlier one
 * already has content (and therefore its closing fence) after it.
 * @param markdown - Raw markdown source, possibly mid-reveal.
 * @returns `markdown` unchanged, or truncated right before an unterminated trailing mermaid fence.
 */
export const holdBackIncompleteMermaidFence = (markdown: string): string => {
    const lines = markdown.split("\n")
    let lastOpenLine = -1
    for (let i = 0; i < lines.length; i++) {
        if (/^```mermaid[ \t]*$/.test(lines[i].trimEnd())) {
            lastOpenLine = i
        }
    }
    if (lastOpenLine === -1) {
        return markdown
    }
    const isClosed = lines.slice(lastOpenLine + 1).some((line) => line.trim() === "```")
    return isClosed ? markdown : lines.slice(0, lastOpenLine).join("\n").trimEnd()
}

/**
 * Scans markdown for mermaid blocks and pairs each with the caption paragraph that
 * immediately follows it (a figure-caption line, Vietnamese or English), keyed by trimmed source.
 * @param markdown - Raw markdown source.
 * @returns Caption text keyed by trimmed mermaid source.
 */
export const extractMermaidCaptions = (markdown: string): Record<string, string> => {
    const captions: Record<string, string> = {}
    // Reset lastIndex defensively since the regex is module-scoped + global.
    MERMAID_CAPTION_REGEX.lastIndex = 0
    for (let match = MERMAID_CAPTION_REGEX.exec(markdown); match; match = MERMAID_CAPTION_REGEX.exec(markdown)) {
        const code = match[1].trim()
        // Strip surrounding italic markers authors wrap captions in (*...*).
        const caption = match[2].trim().replace(/^\*+|\*+$/g, "").trim()
        // Only adopt lines that read as figure captions, not following prose.
        if (/^(Hình|Figure)\b/i.test(caption)) { // vn-ok: matches the VI figure word in lesson prose
            captions[code] = caption
        }
    }
    return captions
}

/**
 * Removes each mermaid figure-caption paragraph ("Figure N: …", either language) from the source
 * so it isn't rendered twice — the diagram now shows it as a real `<figcaption>`. Non-caption
 * paragraphs after a fence are left intact.
 * @param markdown - Raw markdown source.
 * @returns Markdown with figure-caption paragraphs stripped.
 */
const stripMermaidCaptions = (markdown: string): string => {
    MERMAID_CAPTION_REGEX.lastIndex = 0
    return markdown.replace(MERMAID_CAPTION_REGEX, (match: string, _code: string, caption: string) => {
        const clean = caption.trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(clean)) { // vn-ok: matches the VI figure word in lesson prose
            // keep the fence + the blank line(s) after it, drop only the caption text
            return match.slice(0, match.lastIndexOf(caption))
        }
        return match
    })
}

/**
 * Strips Anki-style cloze markers `{{cN::term}}` (or `{{cN::term::distractorA,
 * distractorB}}` — the optional trailing group is the quiz's curated
 * confuser set, dropped entirely here) down to just the term, so a flashcard
 * answer renders cleanly everywhere (reviewer / due / quiz full answer). The
 * `cN::` prefix makes the pattern distinctive — it never collides with
 * template braces like `{{ user.name }}` in lesson code samples.
 * @param markdown - Raw markdown that may carry cloze markers.
 */
const stripClozeMarkers = (markdown: string): string =>
    markdown.replace(/\{\{c\d+::([\s\S]*?)(?:::[\s\S]*?)?\}\}/g, "$1")

/** Intrinsic type scale on the prose root (independent of {@link MarkdownContentProps.reading}). */
export type MarkdownDensity = "default" | "compact" | "caption"

/** Foreground colour role on the prose root. */
export type MarkdownTone = "default" | "muted"

/** Whether paragraphs keep document rhythm or sit flush as an embedded passenger. */
export type MarkdownFlow = "document" | "embedded"

/** Italic emphasis on the whole prose root. */
export type MarkdownEmphasis = "normal" | "italic"

/** Clamp each paragraph to this many visible lines (preview / list snip). */
export type MarkdownPreviewLines = 1 | 2

/** Props for {@link _MarkdownContent} — presentational; the renderer map already resolved. */
export interface MarkdownContentProps {
    /** Markdown source string. */
    markdown: string
    /**
     * Reading-grade typography for full lesson articles: 16px body, looser line
     * rhythm and a stronger heading ladder. Off by default (compact scale used in
     * cards, chat, flashcards and modals).
     */
    reading?: boolean
    /**
     * Boxes each Interview Arc label (`:::muted` / standalone-bold paragraph) together
     * with its following body into one collapsible `arcsection` — see `map.tsx`.
     * Opt-in (default off) so lesson/challenge content using the same `:::muted`
     * shape for unrelated callouts (e.g. "Input"/"Output") is unaffected. Only the
     * flashcard/mock-interview answer (FlipCard back face) turns this on.
     */
    arcSections?: boolean
    /** Intrinsic type scale on the prose root. Defaults to `"default"`. */
    density?: MarkdownDensity
    /** Foreground colour role on the prose root. Defaults to `"default"`. */
    tone?: MarkdownTone
    /** Document rhythm vs flush embedded paragraphs. Defaults to `"document"`. */
    flow?: MarkdownFlow
    /** Italic emphasis on the prose root. Defaults to `"normal"`. */
    emphasis?: MarkdownEmphasis
    /** Clamp each paragraph to 1 or 2 visible lines (omit for no clamp). */
    previewLines?: MarkdownPreviewLines
    /** The element-renderer map, already resolved (theme + i18n baked in). */
    components: Components
}

/**
 * Renders markdown with GFM and shared typography aligned with the app theme.
 *
 * Presentational: the connected half resolves the active theme/translator into
 * the `components` renderer map; this file only runs the pure markdown-source
 * transforms (hold-back-incomplete-fence, strip captions/cloze) and renders
 * `ReactMarkdown`. Marked `"use client"` via the connected half.
 * @see Story: .storybook/stories/blocks/rendering/MarkdownContent/MarkdownContent.stories
 * @param props - {@link MarkdownContentProps}
 */
export const _MarkdownContent = ({
    markdown,
    reading = false,
    arcSections = false,
    density = "default",
    tone = "default",
    flow = "document",
    emphasis = "normal",
    previewLines,
    components,
}: MarkdownContentProps) => {
    // hold back an unterminated trailing mermaid fence FIRST — markdown streamed in
    // progressively (typewriter reveal, AI token stream) walks through every partial
    // length of a diagram's source, and parsing those mid-fence snapshots is what
    // throws mermaid's "Syntax error in text". The rest of the pipeline only ever
    // sees a diagram once its fence is fully closed.
    const stableMarkdown = useMemo(() => holdBackIncompleteMermaidFence(markdown), [markdown])
    // Strip mermaid figure-captions (rendered as `<figcaption>`) + cloze markers (rendered plain).
    const renderedMarkdown = useMemo(
        () => stripClozeMarkers(stripMermaidCaptions(stableMarkdown)),
        [stableMarkdown],
    )
    return (
        <div
            className={cn(
                "min-w-0 text-foreground",
                // Reading lessons: NO uniform space-y — each block renderer carries its own
                // asymmetric margin (more above headings than below) for a real section rhythm.
                // Compact (cards / chat / flashcards) keeps the tight uniform rhythm.
                reading
                    ? "text-base leading-7 [&>*:first-child]:mt-0 [&>*:last-child]:mb-0"
                    : "space-y-2 text-sm leading-relaxed",
                // Presentation axes (contract D) — mirror composites/viewers/MarkdownContent.
                density === "compact" && "text-sm",
                density === "caption" && "text-xs",
                tone === "muted" && "text-muted",
                flow === "embedded" && "[&_p]:m-0",
                emphasis === "italic" && "italic",
                previewLines === 1 && "[&_p]:line-clamp-1",
                previewLines === 2 && "[&_p]:line-clamp-2",
            )}
        >
            <ReactMarkdown
                remarkPlugins={arcSections ? REMARK_PLUGINS_ARC : REMARK_PLUGINS}
                components={components}
            >
                {renderedMarkdown}
            </ReactMarkdown>
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Accordion,
    Alert,
    Button,
